INSERT INTO public.expeditions (slug, name, code, region, year, start_date, end_date, platform, themes, summary, leader, team_size, highlights, route_stops, image_key) VALUES
('isea-2026-antarctic-44','44th Indian Scientific Expedition to Antarctica','ISEA-44','Antarctic',2026,'2025-11-08','2026-04-12','Maitri & Bharati Stations','{"Cryosphere","Coastal Oceanography","Polar Engineering"}','A full summer and winter-over season focused on ice-shelf stability, coastal ocean observations and resilient station systems across the Indian Antarctic programme.','Dr. Ananya Rao',74,'{"Autonomous ocean mooring installed off the Larsemann coast","New snow-radar transects completed across Schirmacher Oasis","Station microgrid control system commissioned"}','[{"name":"Cape Town","note":"Cargo staging and personnel transfer"},{"name":"Maitri Station","note":"Ice and engineering programme"},{"name":"Larsemann Hills","note":"Coastal ocean mooring deployment"},{"name":"Bharati Station","note":"Marine and atmosphere observations"}]','ice-shelf'),
('iare-2026-arctic-spring','Indian Arctic Expedition — Spring Campaign 2026','IARE-2026SP','Arctic',2026,'2026-03-18','2026-06-10','Himadri Station, Ny-Ålesund','{"Snow Science","Atmospheric Science","Fjord Ecology"}','Spring observations at Himadri examine snow-albedo change, Arctic haze transport and the seasonal awakening of Kongsfjorden ecosystems.','Dr. Ritu Menon',20,'{"Daily snow albedo transect established","Arctic haze event sampled from surface to Zeppelin ridge","First spring plankton bloom profiles collected"}','[{"name":"Longyearbyen","note":"Arctic logistics hub"},{"name":"Ny-Ålesund","note":"Himadri Station base"},{"name":"Zeppelin Ridge","note":"Atmospheric sampling"},{"name":"Kongsfjorden","note":"Spring ecosystem survey"}]','arctic-fjord'),
('sore-2025-09','Southern Ocean Research Expedition — Leg 9','SORE-09','Southern Ocean',2025,'2025-12-12','2026-03-30','ORV Sagar Nidhi','{"Oceanography","Marine Biogeochemistry","Climate"}','Leg 9 followed a repeat meridional transect to investigate carbon uptake, ocean heat storage and changing plankton communities south of 55 degrees.','Dr. Meera Krishnan',44,'{"Fifty-two hydrographic stations occupied","Three biogeochemical floats deployed","High-resolution carbon uptake section completed"}','[{"name":"Chennai","note":"Mobilisation and departure"},{"name":"Subantarctic Zone","note":"Carbon and plankton survey"},{"name":"Polar Front","note":"Repeat hydrography"},{"name":"Prydz Bay","note":"Southern station occupation"}]','southern-ocean'),
('himansh-2026','Himansh Glacier Observatory Campaign 2026','HIM-2026','Himalaya',2026,'2026-05-10','2026-10-18','Himansh Station, Chandra Basin','{"Glaciology","Hydrology","Climate Adaptation"}','A high-altitude campaign combining glacier mass balance measurements with downstream water-security studies and community climate observations.','Dr. Kabir Nandy',21,'{"Winter snow accumulation mapped on nine glaciers","New meltwater gauges added to the Chandra basin","Community water diaries launched in three villages"}','[{"name":"Manali","note":"Acclimatisation and equipment checks"},{"name":"Himansh Station","note":"Observatory base"},{"name":"Bara Shigri Glacier","note":"Mass balance survey"},{"name":"Chandra Valley","note":"Water-security fieldwork"}]','himalaya'),
('isea-2022-antarctic-40','40th Indian Scientific Expedition to Antarctica','ISEA-40','Antarctic',2022,'2021-11-16','2022-03-28','Maitri & Bharati Stations','{"Geology","Meteorology","Polar Biology"}','The fortieth Antarctic season combined station resupply with long-term meteorological records, geology traverses and coastal wildlife monitoring.','Dr. Sunita Bhalla',59,'{"Twenty-year meteorology record consolidated","New geology transect completed near Wohlthat Mountains","Weddell seal observation programme expanded"}','[{"name":"Cape Town","note":"Staging and embarkation"},{"name":"Maitri Station","note":"Meteorology and geology operations"},{"name":"Wohlthat Mountains","note":"Geological traverse"},{"name":"Bharati Station","note":"Coastal biology surveys"}]','station-night'),
('iare-2023-arctic-autumn','Indian Arctic Expedition — Autumn Campaign 2023','IARE-2023A','Arctic',2023,'2023-08-19','2023-10-04','Himadri Station, Ny-Ålesund','{"Permafrost","Atmospheric Science","Sea Ice"}','An autumn transition campaign documenting permafrost freeze-back, boundary-layer chemistry and early sea-ice formation in the Svalbard archipelago.','Dr. Vikram Shetty',16,'{"Permafrost borehole network serviced before winter","Autumn aerosol composition record completed","Sea-ice formation observed at twelve fjord sites"}','[{"name":"Longyearbyen","note":"Arrival and field mobilisation"},{"name":"Ny-Ålesund","note":"Station operations"},{"name":"Brøgger Peninsula","note":"Permafrost boreholes"},{"name":"Kongsfjorden","note":"Sea-ice monitoring"}]','aurora'),
('sore-2022-06','Southern Ocean Research Expedition — Leg 6','SORE-06','Southern Ocean',2022,'2022-01-11','2022-03-14','ORV Sagar Kanya','{"Oceanography","Marine Biology","Atmospheric Science"}','The sixth Southern Ocean leg built a baseline for ocean acidification, phytoplankton diversity and marine aerosol measurements across the Indian sector.','Dr. Meera Krishnan',36,'{"First regional ocean acidification baseline assembled","DNA samples collected from 34 plankton stations","Marine aerosol filter archive established"}','[{"name":"Port Louis","note":"Vessel mobilisation"},{"name":"Subtropical Front","note":"Baseline stations"},{"name":"Polar Front","note":"Plankton and aerosol survey"},{"name":"Antarctic Circumpolar Current","note":"Southernmost transect"}]','ship-deck');
